// generated by tools/build_verse_manifests.js from jst_english.js — Dual-view English for the chapters of jst_verses/jstjohn.js
registerEnglish([["John",1,1,"In the beginning was the gospel preached through the Son. And the gospel was the word, and the word was with the Son, and the Son was with God, and the Son was of God."],["John",1,2,"The same was in the beginning with God."],["John",1,3,"All things were made by him; and without him was not anything made which was made."],["John",1,4,"In him was the gospel, and the gospel was the life, and the life was the light of men;"],["John",1,5,"And the light shineth in the world, and the world perceiveth it not."],["John",1,6,"There was a man sent from God, whose name was John."],["John",1,7,"The same came into the world for a witness, to bear witness of the light, to bear record of the gospel through the Son, unto all, that through him men might believe."],["John",1,8,"He was not that light, but came to bear witness of that light,"],["John",1,9,"Which was the true light, which lighteth every man who cometh into the world;"],["John",1,10,"Even the Son of God. He who was in the world, and the world was made by him, and the world knew him not."],["John",1,11,"He came unto his own, and his own received him not."],["John",1,12,"But as many as received him, to them gave he power to become the sons of God; only to them who believe on his name."],["John",1,13,"He was born, not of blood, nor of the will of the flesh, nor of the will of man, but of God."],["John",1,14,"And the same word was made flesh, and dwelt among us, and we beheld his glory, the glory as of the Only Begotten of the Father, full of grace and truth."],["John",1,15,"John bear witness of him, and cried, saying, This is he of whom I spake; He who cometh after me, is preferred before me; for he was before me."],["John",1,16,"For in the beginning was the Word, even the Son, who is made flesh, and sent unto us by the will of the Father. And as many as believe on his name shall receive of his fullness. And of his fullness have all we received, even immortality and eternal life, through his grace."],["John",1,17,"For the law was given through Moses, but life and truth came through Jesus Christ."],["John",1,18,"For the law was after a carnal commandment, to the administration of death; but the gospel was after the power of an endless life, through Jesus Christ, the Only Begotten Son, who is in the bosom of the Father."],["John",1,19,"And no man hath seen God at any time, except he hath borne record of the Son; for except it is through him no man can be saved."],["John",1,20,"And this is the record of John, when the Jews sent priests and Levites from Jerusalem, to ask him; Who art thou?"],["John",1,21,"And he confessed, and denied not that he was Elias; but confessed, saying; I am not the Christ."],["John",1,22,"And they asked him, saying; How then art thou Elias? And he said, I am not that Elias who was to restore all things. And they asked him, saying, Art thou that prophet? And he answered, No."],["John",1,23,"Then said they unto him, Who art thou? that we may give an answer to them that sent us. What sayest thou of thyself?"],["John",1,24,"He said, I am the voice of one crying in the wilderness, Make straight the way of the Lord, as saith the prophet Esaias."],["John",1,25,"And they who were sent were of the Pharisees."],["John",1,26,"And they asked him, and said unto him; Why baptizest thou then, if thou be not the Christ, nor Elias who was to restore all things, neither that prophet?"],["John",1,27,"John answered them, saying; I baptize with water, but there standeth one among you, whom ye know not;"],["John",1,28,"He it is of whom I bear record. He is that prophet, even Elias, who, coming after me, is preferred before me, whose shoe’s latchet I am not worthy to unloose, or whose place I am not able to fill; for he shall baptize, not only with water, but with fire, and with the Holy Ghost."],["John",1,29,"The next day John seeth Jesus coming unto him, and said; Behold the Lamb of God, who taketh away the sin of the world!"],["John",1,30,"And John bare record of him unto the people, saying, This is he of whom I said; After me cometh a man who is preferred before me; for he was before me, and I knew him, and that he should be made manifest to Israel; therefore am I come baptizing with water."],["John",1,31,"And John bare record, saying; When he was baptized of me, I saw the Spirit descending from heaven like a dove, and it abode upon him."],["John",1,32,"And I knew him; for he who sent me to baptize with water, the same said unto me; Upon whom thou shalt see the Spirit descending, and remaining on him, the same is he who baptizeth with the Holy Ghost."],["John",1,33,"And I saw, and bare record that this is the Son of God."],["John",1,34,"These things were done in Bethabara, beyond Jordan, where John was baptizing."],["John",2,1,"When therefore the Pharisees had heard that Jesus made and baptized more disciples than John,"],["John",2,2,"They sought more diligently some means that they might put him to death; for many received John as a prophet, but they believed not on Jesus."],["John",2,3,"Now the Lord knew this, though he himself baptized not so many as his disciples;"],["John",2,4,"For he suffered them for an example, preferring one another."],["John",2,5,"For unto such hath God promised his Spirit. And they who worship him, must worship in spirit and in truth."],["John",3,1,"No man can come unto me, except he doeth the will of my Father who hath sent me. And this is the will of him who hath sent me, that ye receive the Son; for the Father beareth record of him; and he who receiveth the testimony, and doeth the will of him who sent me, I will raise up in the resurrection of the just."],["John",4,1,"Peter saith unto him, Thou needest not to wash my feet. Jesus answered him, If I wash thee not, thou hast no part with me."],["John",4,2,"Simon Peter saith unto him, Lord, not my feet only, but also my hands and my head."],["John",4,3,"Jesus saith to him, He that has washed his hands and his head, needeth not save to wash his feet, but is clean every whit; and ye are clean, but not all. Now this was the custom of the Jews under their law; wherefore, Jesus did this that the law might be fulfilled."],["John",5,1,"Hereafter I will not talk much with you; for the prince of darkness, who is of this world, cometh, but hath no power over me, but he hath power over you."]]);
